const svg=$('#erm-svg'), out=$('#erm-out');
const cx=$('#erm-cx'), cxL=$('#erm-cx-lbl'), mSl=$('#erm-m'), mL=$('#erm-m-lbl'), resample=$('#erm-resample');
const W=640,H=300, padL=54, padR=20, padT=22, padB=40;
const x0=padL, x1=W-padR, y0=H-padB, y1=padT;
let pts=[]; // {x,y} in [0,1]^2 (y is noisy label/target)
// ground truth: smooth step centered at 0.5
function truth(x){ return 1/(1+Math.exp(-12*(x-0.5))); }
function gen(m){
  pts=[];
  for(let i=0;i<m;i++){
    const x=Math.random();
    const noise=(Math.random()-0.5)*0.5;
    pts.push({x, y:Math.max(0,Math.min(1, truth(x)+noise))});
  }
}
// fit polynomial of degree d by least squares (normal equations, small d)
function fit(d){
  const n=pts.length;
  const X=[]; const Y=[];
  for(const p of pts){ const row=[]; for(let j=0;j<=d;j++) row.push(Math.pow(p.x,j)); X.push(row); Y.push(p.y); }
  // XtX (d+1 square), XtY
  const k=d+1;
  const A=Array.from({length:k},()=>new Array(k).fill(0));
  const b=new Array(k).fill(0);
  for(let r=0;r<n;r++) for(let i=0;i<k;i++){ b[i]+=X[r][i]*Y[r]; for(let j=0;j<k;j++) A[i][j]+=X[r][i]*X[r][j]; }
  // ridge nudge for numerical stability at high degree
  for(let i=0;i<k;i++) A[i][i]+=1e-6;
  return solve(A,b);
}
function solve(A,b){ // Gaussian elimination
  const k=b.length; const M=A.map((row,i)=>[...row,b[i]]);
  for(let c=0;c<k;c++){
    let piv=c; for(let r=c+1;r<k;r++) if(Math.abs(M[r][c])>Math.abs(M[piv][c])) piv=r;
    [M[c],M[piv]]=[M[piv],M[c]];
    const d=M[c][c]||1e-12;
    for(let j=c;j<=k;j++) M[c][j]/=d;
    for(let r=0;r<k;r++){ if(r===c) continue; const f=M[r][c]; for(let j=c;j<=k;j++) M[r][j]-=f*M[c][j]; }
  }
  return M.map(row=>row[k]);
}
function evalP(coef,x){ let s=0; for(let j=0;j<coef.length;j++) s+=coef[j]*Math.pow(x,j); return s; }
function mse(coef,sample){ let s=0; for(const p of sample) s+=Math.pow(evalP(coef,p.x)-p.y,2); return s/sample.length; }
function trueRisk(coef){ // integrate (p(x)-truth(x))^2 over [0,1] numerically + noise variance
  let s=0; const N=200;
  for(let i=0;i<N;i++){ const x=(i+0.5)/N; s+=Math.pow(evalP(coef,x)-truth(x),2); }
  return s/N + (0.25*0.25)/3; // + Var of uniform(-0.25,0.25) noise = (0.5)^2/12
}
const SX=x=>x0+x*(x1-x0);
const SY=y=>y0+y*(y1-y0);
function render(){
  svg.innerHTML='';
  const d=+cx.value;
  cxL.textContent='degree '+d;
  mL.textContent=pts.length+' points';
  // axes
  svg.appendChild(SVG('line',{x1:x0,y1:y0,x2:x1,y2:y0,stroke:'var(--line)','stroke-width':1}));
  svg.appendChild(SVG('line',{x1:x0,y1:y0,x2:x0,y2:y1,stroke:'var(--line)','stroke-width':1}));
  const ax=SVG('text',{x:(x0+x1)/2,y:H-8,'text-anchor':'middle','font-size':12,fill:'var(--mute)'}); ax.textContent='x'; svg.appendChild(ax);
  const ay=SVG('text',{x:14,y:(y0+y1)/2,'text-anchor':'middle','font-size':12,fill:'var(--mute)',transform:`rotate(-90 14 ${(y0+y1)/2})`}); ay.textContent='y'; svg.appendChild(ay);
  // truth curve
  let dt='M';
  for(let i=0;i<=120;i++){ const x=i/120; dt+=` ${SX(x).toFixed(1)} ${SY(truth(x)).toFixed(1)}`; }
  svg.appendChild(SVG('path',{d:dt,fill:'none',stroke:'var(--mute)','stroke-width':1.4,'stroke-dasharray':'5 4'}));
  // fitted curve
  const coef=fit(d);
  let df='M';
  for(let i=0;i<=200;i++){ const x=i/200; const yy=Math.max(-0.3,Math.min(1.3,evalP(coef,x))); df+=` ${SX(x).toFixed(1)} ${SY(yy).toFixed(1)}`; }
  svg.appendChild(SVG('path',{d:df,fill:'none',stroke:'var(--yellow)','stroke-width':2.2}));
  // data points
  for(const p of pts) svg.appendChild(SVG('circle',{cx:SX(p.x),cy:SY(p.y),r:3.4,fill:'var(--blue)',opacity:0.85}));
  // legend
  function leg(x,y,c,t){ svg.appendChild(SVG('line',{x1:x,y1:y,x2:x+22,y2:y,stroke:c,'stroke-width':2.4})); const tt=SVG('text',{x:x+28,y:y+4,'font-size':11,fill:'var(--mute)'}); tt.textContent=t; svg.appendChild(tt); }
  leg(x1-150,y1+6,'var(--mute)','truth');
  leg(x1-150,y1+22,'var(--yellow)','fit (deg '+d+')');
  const emp=mse(coef,pts), tr=trueRisk(coef);
  out.textContent =
    `degree d = ${d}, sample size m = ${pts.length}\n`+
    `empirical risk  R̂(h_S) = ${emp.toFixed(4)}\n`+
    `population risk R(h_S) ≈ ${tr.toFixed(4)}   (noise floor ≈ 0.0208)\n`+
    `generalization gap R − R̂ = ${(tr-emp).toFixed(4)}` +
    (d>=8 ? '   ← overfitting: gap blows up' : (d<=1 ? '   ← underfitting: both high' : ''));
}
cx.addEventListener('input',render);
mSl.addEventListener('input',()=>{ gen(+mSl.value); render(); });
resample.addEventListener('click',()=>{ gen(+mSl.value); render(); });
gen(+mSl.value); render();

const eps=$('#pac-eps'), epsL=$('#pac-eps-lbl'), del=$('#pac-del'), delL=$('#pac-del-lbl');
const hSl=$('#pac-h'), hL=$('#pac-h-lbl'), out=$('#pac-out'), svg=$('#pac-svg');
const W=640,H=200, padL=54,padR=20,padT=20,padB=40;
const x0=padL,x1=W-padR,y0=H-padB,y1=padT;
function compute(){
  const e=+eps.value, d=+del.value, lh=(+hSl.value)*Math.LN2; // ln|H|
  const real=Math.ceil((1/e)*(lh+Math.log(1/d)));
  const agno=Math.ceil((2/(e*e))*(lh+Math.log(2/d)));
  return {e,d,lh,real,agno};
}
function render(){
  const {e,d,lh,real,agno}=compute();
  epsL.textContent='ε = '+e.toFixed(2);
  delL.textContent='δ = '+d.toFixed(2);
  hL.textContent='|H| = 2^'+hSl.value+'  (ln|H| = '+lh.toFixed(2)+')';
  out.innerHTML =
    'Realizable: $m \\ge \\frac{1}{\\varepsilon}\\!\\left(\\ln|\\mathcal{H}|+\\ln\\frac1\\delta\\right) = '+real+'$ &nbsp;samples<br>'+
    'Agnostic: &nbsp;$m \\ge \\frac{2}{\\varepsilon^{2}}\\!\\left(\\ln|\\mathcal{H}|+\\ln\\frac2\\delta\\right) = '+agno+'$ &nbsp;samples';
  if(window.renderMathInElement) window.renderMathInElement(out,{throwOnError:false,
    strict:(c)=>c==='unicodeTextInMathMode'?'ignore':'warn',delimiters:[{left:'$',right:'$',display:false}]});
  // plot agnostic m vs eps (log-y) for current delta, |H|
  svg.innerHTML='';
  svg.appendChild(SVG('line',{x1:x0,y1:y0,x2:x1,y2:y0,stroke:'var(--line)'}));
  svg.appendChild(SVG('line',{x1:x0,y1:y0,x2:x0,y2:y1,stroke:'var(--line)'}));
  const ax=SVG('text',{x:(x0+x1)/2,y:H-8,'text-anchor':'middle','font-size':11,fill:'var(--mute)'}); ax.textContent='accuracy ε'; svg.appendChild(ax);
  const ay=SVG('text',{x:14,y:(y0+y1)/2,'text-anchor':'middle','font-size':11,fill:'var(--mute)',transform:`rotate(-90 14 ${(y0+y1)/2})`}); ay.textContent='m (log)'; svg.appendChild(ay);
  const emin=0.02, emax=0.5;
  const mAt=(ee)=> (2/(ee*ee))*(lh+Math.log(2/d));
  const mvals=[]; for(let i=0;i<=120;i++){ const ee=emin+(emax-emin)*i/120; mvals.push(mAt(ee)); }
  const lmax=Math.log(Math.max(...mvals)), lmin=Math.log(Math.min(...mvals));
  const SX=ee=>x0+(ee-emin)/(emax-emin)*(x1-x0);
  const SY=m=>y0+(Math.log(m)-lmin)/((lmax-lmin)||1)*(y1-y0);
  let dpath='M';
  for(let i=0;i<=120;i++){ const ee=emin+(emax-emin)*i/120; dpath+=` ${SX(ee).toFixed(1)} ${SY(mAt(ee)).toFixed(1)}`; }
  svg.appendChild(SVG('path',{d:dpath,fill:'none',stroke:'var(--cyan)','stroke-width':2.2}));
  // marker at current eps
  svg.appendChild(SVG('circle',{cx:SX(e),cy:SY(agno),r:5,fill:'var(--yellow)'}));
  const lbl=SVG('text',{x:SX(e),y:SY(agno)-10,'text-anchor':'middle','font-size':11,fill:'var(--yellow)'}); lbl.textContent='m='+agno; svg.appendChild(lbl);
}
[eps,del,hSl].forEach(el=>el.addEventListener('input',render));
render();

const svg=$('#vc-svg'), out=$('#vc-out'), cls=$('#vc-class'), reset=$('#vc-reset');
const W=640,H=300;
let pts=[]; // {x,y,label} label in {0,1}
function defaults(kind){
  if(kind==='threshold'||kind==='interval'){
    pts=[{x:160,y:150,label:1},{x:320,y:150,label:0},{x:480,y:150,label:1}];
  } else {
    pts=[{x:200,y:90,label:1},{x:440,y:110,label:0},{x:300,y:230,label:1}];
  }
}
// ---- realizability tests ----
function thresholdRealizable(){ // 1D: order by x; label must be monotone of form 0..0 1..1 OR 1..1 0..0
  const s=[...pts].sort((a,b)=>a.x-b.x).map(p=>p.label);
  // a threshold h(x)=1[x>=a] or 1[x<=a]; realizable iff labels are "sorted" one way
  const asc=isStep(s), desc=isStep([...s].reverse());
  return asc||desc;
}
function isStep(arr){ // all 0s then all 1s
  let seen1=false;
  for(const v of arr){ if(v===1) seen1=true; else if(seen1) return false; }
  return true;
}
function intervalRealizable(){ // 1D interval: the 1-labels must be contiguous in x-order (or all 0)
  const s=[...pts].sort((a,b)=>a.x-b.x).map(p=>p.label);
  let started=false,ended=false;
  for(const v of s){ if(v===1){ if(ended) return false; started=true; } else if(started) ended=true; }
  return true;
}
function halfplaneRealizable(){ // linearly separable in 2D: brute-force LP via small perceptron / convex check
  const pos=pts.filter(p=>p.label===1), neg=pts.filter(p=>p.label===0);
  if(pos.length===0||neg.length===0) return true;
  // perceptron with bias on a few hundred passes
  let w=[0,0], b=0;
  for(let it=0;it<2000;it++){
    let ok=true;
    for(const p of pts){ const s=w[0]*p.x+w[1]*p.y+b; const t=p.label===1?1:-1;
      if(s*t<=0){ ok=false; w[0]+=t*p.x*0.0005; w[1]+=t*p.y*0.0005; b+=t*0.5; } }
    if(ok) return true;
  }
  // fallback exact: convex hulls disjoint? approximate by final perceptron check
  for(const p of pts){ const s=w[0]*p.x+w[1]*p.y+b; const t=p.label===1?1:-1; if(s*t<=0) return false; }
  return true;
}
function realizable(){
  const k=cls.value;
  if(k==='threshold') return thresholdRealizable();
  if(k==='interval') return intervalRealizable();
  return halfplaneRealizable();
}
function vcOf(k){ return k==='threshold'?1:k==='interval'?2:3; }
// shattered? test all 2^n labelings realizable for current class & point positions
function shattered(){
  const n=pts.length, saved=pts.map(p=>p.label);
  let allOK=true;
  for(let m=0;m<(1<<n);m++){
    for(let i=0;i<n;i++) pts[i].label=(m>>i)&1;
    if(!realizable()){ allOK=false; break; }
  }
  pts.forEach((p,i)=>p.label=saved[i]);
  return allOK;
}
function render(){
  svg.innerHTML='';
  const k=cls.value;
  // draw separating hint geometry
  if(k==='threshold'||k==='interval'){
    svg.appendChild(SVG('line',{x1:60,y1:150,x2:580,y2:150,stroke:'var(--line)','stroke-width':1.5}));
  }
  const rz=realizable();
  // points
  for(const p of pts){
    const fill=p.label===1?'var(--cyan)':'var(--pink)';
    svg.appendChild(SVG('circle',{cx:p.x,cy:p.y,r:11,fill,stroke:'var(--ink)','stroke-width':1.5,style:'cursor:pointer','data-pt':pts.indexOf(p)}));
    const t=SVG('text',{x:p.x,y:p.y+4,'text-anchor':'middle','font-size':12,fill:'#0b0d10','font-weight':700,'pointer-events':'none'});
    t.textContent=p.label; svg.appendChild(t);
  }
  // legend
  const lg=SVG('text',{x:60,y:280,'font-size':11,fill:'var(--mute)'}); lg.textContent='label 1 = cyan, 0 = pink — click a point to flip'; svg.appendChild(lg);
  const sh=shattered();
  out.textContent =
    `class: ${k} (VC = ${vcOf(k)}),  points placed: ${pts.length}\n`+
    `current labeling realizable? ${rz?'YES ✓':'NO ✗'}\n`+
    `is this point set shattered (all 2^${pts.length} = ${1<<pts.length} labelings realizable)? ${sh?'YES — shattered':'NO'}`;
}
svg.addEventListener('click',e=>{
  const i=e.target&&e.target.getAttribute&&e.target.getAttribute('data-pt');
  if(i!==null&&i!==undefined){ const idx=+i; pts[idx].label=pts[idx].label?0:1; render(); }
});
cls.addEventListener('change',()=>{ defaults(cls.value); render(); });
reset.addEventListener('click',()=>{ defaults(cls.value); render(); });
defaults('halfplane'); render();

const svg=$('#uc-svg'), out=$('#uc-out'), dSl=$('#uc-d'), dL=$('#uc-d-lbl'), delSl=$('#uc-del'), delL=$('#uc-del-lbl');
const W=640,H=320,padL=56,padR=20,padT=24,padB=42;
const x0=padL,x1=W-padR,y0=H-padB,y1=padT;
const mMin=10,mMax=20000;
function bound(m,d,del){ // O(.) with constant 1: sqrt((d ln(2m/d) + ln(1/del))/m), capped at 1
  const v=(d*Math.log(2*m/d)+Math.log(1/del))/m;
  return Math.min(1, Math.sqrt(v));
}
function render(){
  svg.innerHTML='';
  const d=+dSl.value, del=+delSl.value;
  dL.textContent='d = '+d;
  delL.textContent='δ = '+del.toFixed(2);
  // axes (log-x)
  svg.appendChild(SVG('line',{x1:x0,y1:y0,x2:x1,y2:y0,stroke:'var(--line)'}));
  svg.appendChild(SVG('line',{x1:x0,y1:y0,x2:x0,y2:y1,stroke:'var(--line)'}));
  const lminX=Math.log(mMin),lmaxX=Math.log(mMax);
  const SX=m=>x0+(Math.log(m)-lminX)/(lmaxX-lminX)*(x1-x0);
  const SY=v=>y0+v*(y1-y0); // v in [0,1]
  // gridlines y
  for(let g=0;g<=1.0001;g+=0.25){ svg.appendChild(SVG('line',{x1:x0,y1:SY(g),x2:x1,y2:SY(g),stroke:'var(--line)','stroke-dasharray':'2 5',opacity:0.5}));
    const tg=SVG('text',{x:x0-8,y:SY(g)+4,'text-anchor':'end','font-size':10,fill:'var(--mute)'}); tg.textContent=g.toFixed(2); svg.appendChild(tg); }
  // x ticks
  [10,100,1000,10000].forEach(m=>{ const tx=SVG('text',{x:SX(m),y:y0+16,'text-anchor':'middle','font-size':10,fill:'var(--mute)'}); tx.textContent=m>=1000?(m/1000)+'k':m; svg.appendChild(tx);
    svg.appendChild(SVG('line',{x1:SX(m),y1:y0,x2:SX(m),y2:y0+4,stroke:'var(--mute)'})); });
  const ax=SVG('text',{x:(x0+x1)/2,y:H-6,'text-anchor':'middle','font-size':12,fill:'var(--mute)'}); ax.textContent='sample size m (log scale)'; svg.appendChild(ax);
  const ay=SVG('text',{x:16,y:(y0+y1)/2,'text-anchor':'middle','font-size':12,fill:'var(--mute)',transform:`rotate(-90 16 ${(y0+y1)/2})`}); ay.textContent='generalization bound'; svg.appendChild(ay);
  // bound curve
  let path='M';
  for(let i=0;i<=200;i++){ const lm=lminX+(lmaxX-lminX)*i/200; const m=Math.exp(lm); path+=` ${SX(m).toFixed(1)} ${SY(bound(m,d,del)).toFixed(1)}`; }
  svg.appendChild(SVG('path',{d:path,fill:'none',stroke:'var(--yellow)','stroke-width':2.4}));
  // mark m where bound drops below 0.1
  let mStar=null; for(let m=mMin;m<=mMax;m*=1.02){ if(bound(m,d,del)<=0.1){ mStar=Math.round(m); break; } }
  if(mStar){ svg.appendChild(SVG('line',{x1:SX(mStar),y1:y0,x2:SX(mStar),y2:SY(0.1),stroke:'var(--cyan)','stroke-dasharray':'4 4'}));
    svg.appendChild(SVG('circle',{cx:SX(mStar),cy:SY(0.1),r:4,fill:'var(--cyan)'})); }
  out.textContent =
    `VC dim d = ${d}, δ = ${del.toFixed(2)}\n`+
    `bound ≈ √((d·ln(2m/d) + ln(1/δ)) / m)  — decays like √(d/m)\n`+
    (mStar?`sample size to push bound below 0.1: m ≈ ${mStar.toLocaleString()}`:'bound stays above 0.1 on this range');
}
dSl.addEventListener('input',render); delSl.addEventListener('input',render);
render();

const svg=$('#rad-svg'), out=$('#rad-out'), cls=$('#rad-class');
const step=$('#rad-step'), run=$('#rad-run'), reset=$('#rad-reset');
const W=640,H=280;
const m=11;
const xs=[]; for(let i=0;i<m;i++) xs.push(60+i*52); // fixed points on a line
const yMid=150;
let signs=new Array(m).fill(1);
let sum=0, count=0;
function bestCorr(signs){
  const k=cls.value;
  if(k==='all'){
    // class realizes every sign pattern: sup (1/m) Σ σ_i h(x_i) with h=±1 free => pick h_i=σ_i => (1/m)Σ1 = 1
    return {val:1, h:signs.slice()};
  }
  // thresholds: h(x)=±1[x>=a] over all a and both polarities; choose split + sign maximizing correlation
  let best=-Infinity, bestH=null;
  for(let split=0;split<=m;split++){
    for(const pol of [1,-1]){
      // h(x_i)= pol if i>=split else -pol
      let c=0; const h=[];
      for(let i=0;i<m;i++){ const hi=(i>=split? pol : -pol); h.push(hi); c+=signs[i]*hi; }
      if(c/m>best){ best=c/m; bestH=h; }
    }
  }
  return {val:best, h:bestH};
}
function draw(){
  svg.innerHTML='';
  svg.appendChild(SVG('line',{x1:40,y1:yMid,x2:W-30,y2:yMid,stroke:'var(--line)','stroke-width':1.5}));
  const {val,h}=bestCorr(signs);
  for(let i=0;i<m;i++){
    // sign label above
    const sUp=signs[i]===1;
    const c=sUp?'var(--cyan)':'var(--pink)';
    svg.appendChild(SVG('circle',{cx:xs[i],cy:yMid,r:9,fill:c,stroke:'var(--ink)','stroke-width':1.3}));
    const t=SVG('text',{x:xs[i],y:yMid+4,'text-anchor':'middle','font-size':12,fill:'#0b0d10','font-weight':700});
    t.textContent=signs[i]===1?'+':'−'; svg.appendChild(t);
    // best-fit hypothesis marker (whether it agrees)
    const agree=h[i]===signs[i];
    const my=h[i]===1?yMid-34:yMid+34;
    svg.appendChild(SVG('rect',{x:xs[i]-7,y:my-7,width:14,height:14,rx:3,fill:agree?'var(--green)':'var(--panel2)',stroke:agree?'var(--green)':'var(--line)','stroke-width':1.3}));
  }
  const cap1=SVG('text',{x:50,y:60,'font-size':11,fill:'var(--cyan)'}); cap1.textContent='σ = random ±1 signs (circles)'; svg.appendChild(cap1);
  const cap2=SVG('text',{x:50,y:H-30,'font-size':11,fill:'var(--green)'}); cap2.textContent='best hypothesis h (squares: above=+1, below=−1, green=agrees with σ)'; svg.appendChild(cap2);
  const avg=count? sum/count : 0;
  out.textContent =
    `class: ${cls.value==='all'?'all sign patterns (rich)':'thresholds (simple)'},  m = ${m} points\n`+
    `this draw: best correlation (1/m)Σ σ_i h(x_i) = ${val.toFixed(3)}\n`+
    `running empirical Rademacher complexity R̂_S = E_σ[sup_h …] ≈ ${avg.toFixed(3)}   (over ${count} draws)\n`+
    (cls.value==='all'?'rich class fits any signs ⇒ R̂_S = 1':'simple class ⇒ R̂_S = Θ(1/√m): shrinks as m grows; the value above is the empirical estimate at m = '+m);
}
function newSigns(){ for(let i=0;i<m;i++) signs[i]=Math.random()<0.5?1:-1; sum+=bestCorr(signs).val; count++; }
step.addEventListener('click',()=>{ newSigns(); draw(); });
run.addEventListener('click',()=>{ for(let i=0;i<50;i++) newSigns(); draw(); });
reset.addEventListener('click',()=>{ sum=0; count=0; signs=new Array(m).fill(1); draw(); });
cls.addEventListener('change',()=>{ sum=0; count=0; draw(); });
newSigns(); draw();

const svg=$('#bv-svg'), out=$('#bv-out'), cxSl=$('#bv-cx'), cxL=$('#bv-cx-lbl'), nSl=$('#bv-noise'), nL=$('#bv-noise-lbl');
const W=640,H=320,padL=56,padR=20,padT=24,padB=42;
const x0=padL,x1=W-padR,y0=H-padB,y1=padT;
// complexity c in [0,1]; bias^2 falls, variance rises
function bias2(c){ return 0.9*Math.exp(-4.5*c); }
function variance(c){ return 0.04+0.85*Math.pow(c,2.2); }
function render(){
  svg.innerHTML='';
  const c=(+cxSl.value)/100, noise=+nSl.value;
  cxL.textContent='complexity = '+(+cxSl.value)+'%';
  nL.textContent='σ² = '+noise.toFixed(2);
  // axes
  svg.appendChild(SVG('line',{x1:x0,y1:y0,x2:x1,y2:y0,stroke:'var(--line)'}));
  svg.appendChild(SVG('line',{x1:x0,y1:y0,x2:x0,y2:y1,stroke:'var(--line)'}));
  const ymax=1.4;
  const SX=cc=>x0+cc*(x1-x0);
  const SY=v=>y0+(v/ymax)*(y1-y0);
  // gridlines
  for(let g=0;g<=ymax+0.001;g+=0.2){ svg.appendChild(SVG('line',{x1:x0,y1:SY(g),x2:x1,y2:SY(g),stroke:'var(--line)','stroke-dasharray':'2 5',opacity:0.45}));
    const tg=SVG('text',{x:x0-8,y:SY(g)+4,'text-anchor':'end','font-size':10,fill:'var(--mute)'}); tg.textContent=g.toFixed(1); svg.appendChild(tg); }
  const ax=SVG('text',{x:(x0+x1)/2,y:H-6,'text-anchor':'middle','font-size':12,fill:'var(--mute)'}); ax.textContent='model complexity →'; svg.appendChild(ax);
  const ay=SVG('text',{x:16,y:(y0+y1)/2,'text-anchor':'middle','font-size':12,fill:'var(--mute)',transform:`rotate(-90 16 ${(y0+y1)/2})`}); ay.textContent='error'; svg.appendChild(ay);
  function curve(fn,col,w){ let p='M'; for(let i=0;i<=160;i++){ const cc=i/160; p+=` ${SX(cc).toFixed(1)} ${SY(fn(cc)).toFixed(1)}`; } svg.appendChild(SVG('path',{d:p,fill:'none',stroke:col,'stroke-width':w})); }
  curve(cc=>bias2(cc),'var(--pink)',2);
  curve(cc=>variance(cc),'var(--cyan)',2);
  curve(cc=>bias2(cc)+variance(cc)+noise,'var(--yellow)',2.6);
  // noise floor
  svg.appendChild(SVG('line',{x1:x0,y1:SY(noise),x2:x1,y2:SY(noise),stroke:'var(--mute)','stroke-dasharray':'4 4'}));
  // optimum (min of total)
  let bestc=0,bestv=Infinity; for(let i=0;i<=400;i++){ const cc=i/400; const v=bias2(cc)+variance(cc)+noise; if(v<bestv){bestv=v;bestc=cc;} }
  svg.appendChild(SVG('line',{x1:SX(bestc),y1:y0,x2:SX(bestc),y2:y1,stroke:'var(--green)','stroke-dasharray':'4 4',opacity:0.8}));
  // current-complexity marker
  const tot=bias2(c)+variance(c)+noise;
  svg.appendChild(SVG('circle',{cx:SX(c),cy:SY(tot),r:5,fill:'var(--yellow)'}));
  // legend
  function leg(x,y,col,t){ svg.appendChild(SVG('line',{x1:x,y1:y,x2:x+20,y2:y,stroke:col,'stroke-width':2.4})); const tt=SVG('text',{x:x+26,y:y+4,'font-size':11,fill:'var(--mute)'}); tt.textContent=t; svg.appendChild(tt); }
  leg(x1-150,y1+4,'var(--pink)','bias²');
  leg(x1-150,y1+20,'var(--cyan)','variance');
  leg(x1-150,y1+36,'var(--yellow)','total');
  out.textContent =
    `complexity = ${(+cxSl.value)}%   (optimum ≈ ${Math.round(bestc*100)}%)\n`+
    `bias² = ${bias2(c).toFixed(3)},  variance = ${variance(c).toFixed(3)},  noise σ² = ${noise.toFixed(2)}\n`+
    `total test error = ${tot.toFixed(3)}` +
    (c<bestc-0.08?'   ← underfit: bias dominates':(c>bestc+0.08?'   ← overfit: variance dominates':'   ← near optimum'));
}
cxSl.addEventListener('input',render); nSl.addEventListener('input',render);
render();
